  await page.screenshot({path:'/tmp/chapter-checks/generated-cover-mobile.png',fullPage:true});
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth),390);
  await page.getByRole('button',{name:'Read again'}).click();
  await expect(page.locator('.status-badge')).toHaveText('Currently reading');
  await page.getByRole('link',{name:'Back to your library'}).click();
  await expect(page.locator('.reading-card')).toHaveCount(1);
  await page.getByRole('button',{name:'Mark as finished'}).click();
  await expect(page.locator('.finished-card')).toHaveCount(1);
  console.log('PASS: production build, empty initialization, file persistence after full process restart, direct shared page, mobile layout, read again and library finish button.');
} finally {
  if(browser) await browser.close();
  if(server?.exitCode===null) await stop();
  await rm(directory,{recursive:true,force:true});
}
